// Generated by scripts/build-grade-solution-steps.py.
globalThis.KENGURU_GRADE_SOLUTION_STEPS = {"2021":{"1":{"steps":[{"text":"В наборе ровно два белых кирпича."},{"text":"Сверим число белых кирпичей в каждой конструкции. Ровно два кирпича только в варианте Г."}]},"2":{"steps":[{"text":"Чтобы держаться за левые руки, дети должны смотреть в противоположные стороны. Таких пар три."},{"text":"Проверим, за какие руки они держатся. Две пары держатся за правые руки, а пятая девочка и шестой мальчик — за левые."}]},"3":{"steps":[{"text":"Сложим части пазла. Прочитаем пример: 12 + 20."},{"text":"Вычисляем: 12 + 20 = 32."}]},"4":{"steps":[{"text":"Ширина ворот — три клетки. Через них может пройти только фигура, у которой каждый горизонтальный ряд помещается в эту ширину."},{"text":"У фигур A, C, D и E есть ряд шире трёх клеток. Проходит только фигура B из варианта Б."}]},"5":{"steps":[{"text":"Рассмотрим произведение 5 · 10 · 15 · … · 100. Десять чисел, кратных 10, уже дают 11 нулей, потому что 100 даёт два."},{"text":"После удаления этих нулей от кратных 10 остаются множители 1, 2, …, 9. В этом наборе число 2 даёт одну двойку, 4 — две, 6 — одну, 8 — три."},{"text":"Каждую из семи двоек можно соединить с одним из множителей, оканчивающихся на 5, чтобы получить ещё один ноль."},{"text":"Всего в конце произведения 11 + 7 = 18 нулей."}]},"6":{"steps":[{"text":"Разделим квадрат на четыре одинаковые части."},{"text":"Разделим одну четверть ещё пополам. Такой рисунок показан в варианте Г."}]},"7":{"steps":[{"text":"В третьей коробке только одна буква — N. Возьмём её."},{"text":"Из первой коробки берём E, из пятой — U."},{"text":"Из четвёртой коробки остаётся взять G."}]},"8":{"steps":[{"text":"Прямоугольник складываем сначала по вертикальной середине, а затем по диагонали."},{"text":"Квадрат складываем сначала по диагонали, а затем пополам."},{"text":"Треугольник складываем два раза пополам. Так подходят все три фигуры."}]},"9":{"steps":[{"text":"Всего десять цифр, а частей должно быть три. Хотя бы одно число будет четырёхзначным."},{"text":"Наименьшая подходящая четырёхзначная часть — 1972. Две оставшиеся части — 502 и 970."},{"text":"Их сумма равна 1972 + 502 + 970 = 3444. При разбиении на два четырёхзначных и одно двузначное число сумма окажется больше."}]},"10":{"steps":[{"text":"Сложим длины четырёх указанных маршрутов: 10 + 12 + 13 + 15 = 50 км."},{"text":"В этой сумме внешний путь А → зоопарк → В → парк → С → порт → А учтён один раз, а внутренний маршрут длиной 15 км — дважды."},{"text":"Длина внешнего пути: 50 − 2 · 15 = 20 км."}]},"11":{"steps":[{"text":"В вершине пирамиды находится А. Во втором слое лежат шарики В, С и Е."},{"text":"В третьем слое лежат шарики Д, ?, Е, С, Д и В."},{"text":"Каждая буква встречается дважды. Пока только буква А встретилась один раз, поэтому она и стоит на месте вопросительного знака."}]},"12":{"steps":[{"text":"Каждое колёсико повернули на одинаковое число делений. Сравним цифры каждого варианта с 6348, учитывая переход через 0."},{"text":"В варианте А все цифры увеличены на 2. В варианте Б все уменьшены на 3."},{"text":"В варианте В первая цифра уменьшена на 2, а вторая на 4. Такой код не мог получиться."}]},"13":{"steps":[{"text":"Пусть Влад взял x яблок. Всего он взял 20 фруктов, значит, груш у него 20 − x."},{"text":"У Луки осталось 20 − x яблок и x груш. Это соответствует утверждению Г."}]},"14":{"steps":[{"text":"Поезд из X идёт втрое медленнее встречного. Пока первый проезжает один перегон, встречный проезжает три."},{"text":"За это время они вместе проходят четыре перегона. Всего между X и Y шесть перегонов, поэтому первый поезд до встречи проходит 6 : 4 = 1,5 перегона."},{"text":"Встреча произойдёт на середине второго перегона от X. На нём и нужен второй путь."}]},"15":{"steps":[{"text":"Сумма чисел в каждом шестиугольнике равна 30. В пустых кружках левого шестиугольника сумма 30 − (3 + 6 + 1 + 2) = 18."},{"text":"В пустых кружках правого шестиугольника сумма 30 − (4 + 6 + 9 + 4) = 7."},{"text":"В среднем шестиугольнике известны суммы 18 и 7, а также число 1. Искомое число равно 30 − 18 − 7 − 1 = 4."}]},"16":{"steps":[{"text":"Сложим площади частей прямоугольника со стороной AB. Его высота равна (12 + 18) : 6 = 5 см."},{"text":"У прямоугольника со стороной CD такая же высота. Сумма площадей его частей равна 18 + 22."},{"text":"Длина CD равна (18 + 22) : 5 = 8 см."}]},"17":{"steps":[{"text":"На маленькой шестерёнке 10 зубцов, на каждой большой — 13. При полном обороте маленькой шестерёнки каждая из больших пройдёт по 10 зубцов."},{"text":"Маленькая шестерёнка вращается по часовой стрелке. Нижняя большая вращается против часовой стрелки, а правая большая — по часовой."},{"text":"Проследим, куда сдвинутся закрашенные зубцы. Получаем положение А."}]},"18":{"steps":[{"text":"Сравнения на весах дают три соотношения: яблоко + апельсин = груша + персик, яблоко + груша < апельсин + персик, груша + апельсин < яблоко + персик."},{"text":"Сложим левую часть первого соотношения с левой частью второго, а правую — с правой. После сокращения получаем: два яблока легче двух персиков."},{"text":"С первым соотношением можно так же объединить третье. Получаем: два апельсина легче двух персиков."},{"text":"Из равенства и сравнения апельсина с персиком следует, что груша легче яблока. Самый тяжёлый фрукт — персик."}]},"19":{"steps":[{"text":"У квадрата четыре оси симметрии: вертикальная, горизонтальная и две диагонали."},{"text":"Отразим три исходные клетки относительно вертикальной оси. Добавим три клетки и получим фигуру из шести клеток."},{"text":"Отразим фигуру в остальных частях квадрата. Три копии по шесть клеток добавят ещё 18, всего нужно закрасить 3 + 18 = 21 клетку.","image":"assets/grade-solution-steps/2021/task-19-1.webp","imageWidth":231,"imageHeight":231}]},"20":{"steps":[{"text":"В восьми вершинах большого куба стоит по одному кубику с красной линией."},{"text":"В каждой из двух диагоналей грани без углов остаётся 7 − 2 = 5 кубиков. Центральный кубик лежит на обеих диагоналях, поэтому таких кубиков 2 · 5 − 1 = 9 на грань."},{"text":"Граней шесть. С учётом восьми угловых кубиков получаем 8 + 6 · 9 = 62."}]},"21":{"steps":[{"text":"Если бы все сказали правду, сумма была бы 1 + 2 + … + 10 = 55. Получилось 36, то есть на 19 меньше."},{"text":"Один тролль может уменьшить сумму не больше чем на 10 − 1 = 9. Двое уменьшат её не больше чем на 18."},{"text":"Трое могут уменьшить сумму на 19. Например, числа 10, 9 и 8 заменим на 1, 1 и 6. Минимум — три тролля."}]},"22":{"steps":[{"text":"Соседние карты должны совпадать по двум символам на общей стороне. У исходной карты пары символов на коротких и длинных сторонах различаются."},{"text":"Для горизонтального ряда нужны карты с треугольником и квадратом на короткой стороне. Это Б и Г."},{"text":"Для вертикального ряда нужны карты со звездой и квадратом на длинной стороне. Это А и В. Карта Д остаётся лишней."}]},"23":{"steps":[{"text":"Обозначим объёмы большой, средней и маленькой бутылок буквами б, с и м. Полки дают равенства 3б + 4м = 64, 2б + 2с + 3м = 64 и 4с + 6м = 64."},{"text":"Сравним первую и вторую полку. После сокращения получим б + м = 2с."},{"text":"На первой полке 3б + 4м = 3(б + м) + м = 6с + м. Следовательно, м = 64 − 6с."},{"text":"Подставим это в равенство для третьей полки: 4с + 6(64 − 6с) = 64. Решаем: 32с = 320, с = 10 децилитров."}]},"24":{"steps":[{"text":"Допустим, первый пират верно ответил на первый вопрос. Тогда второй пират ошибся в первом ответе и должен быть прав во втором."},{"text":"При таком выборе третий пират ошибся в обоих ответах, что противоречит условию."},{"text":"Значит, первый пират прав во втором ответе: алмазов 6. Второй и третий пираты правы в первом ответе: монет 7. Всего 6 + 7 = 13."}]}},"2022":{"1":{"steps":[{"text":"Числа 1, 3 и 5 нечётные, а числа 2, 4 и 6 чётные."},{"text":"Соединив соответствующие тройки точек, получаем вариант Д."}]},"2":{"steps":[{"text":"Когда Миша огибает буёк против часовой стрелки, буёк находится слева от лодки."},{"text":"Лишь буйки с номерами 1 и 3 будут находиться слева от лодки."}]},"3":{"steps":[{"text":"Из примера видим, что двузначное число получается наложением двух символов – символа, отвечающего за десятки, и символа, отвечающего за единицы."},{"text":"Тогда, чтобы записать число 45, необходимо взять символ «40» и объединить его с символом «5»."},{"text":"Получится символ под буквой Г."}]},"4":{"steps":[{"text":"Начнём строить путь луча. Сначала он идёт вверх, вправо и вниз, затем влево, вниз и вправо.","image":"assets/grade-solution-steps/2022/task-04-1.webp","imageWidth":381,"imageHeight":267},{"text":"После этого луч идёт вверх, вправо, вверх, вправо и вниз."},{"text":"Последние повороты ведут влево, вниз, влево и вниз. Луч выходит в точке В."}]},"5":{"steps":[{"text":"Чтобы обойтись наименьшим количеством коробок, Игорю нужно использовать вначале самые вместительные из них."},{"text":"Так 95 = 25 + 25 + 25 + 10 + 10."},{"text":"Итого 5 коробок."}]},"6":{"steps":[{"text":"Если согнуть квадрат по диагонали, можно заметить, что белые части фигуры наложатся на закрашенные."},{"text":"Поэтому площадь закрашенной области равна площади белой области, что даёт половину площади квадрата: 10 · 10 : 2 = 50."}]},"7":{"steps":[{"text":"Чтобы получить наименьшее возможное число, слева необходимо поставить карточку с числом, начинающимся с наименьшей цифры."},{"text":"Поэтому, самой левой карточкой будет 113."},{"text":"То же правило применимо и к остальным карточкам, поэтому их нужно выложить в последовательности 4, 51, 5, 67, 69 и 9."},{"text":"Получаем, что наименьшее возможное составленное из карточек число оканчивается на 699."}]},"8":{"steps":[{"text":"Чтобы чёрная машина могла беспрепятственно выехать из гаража, нужно переставить машину перед ней на 2 клетки вперед."},{"text":"Для этого нужно переставить ту машину, которая находится перед ней и так далее."},{"text":"Всего 4 машины."},{"text":"Смотри рисунок.","image":"assets/grade-solution-steps/2022/task-08-1.webp","imageWidth":381,"imageHeight":315}]},"9":{"steps":[{"text":"Последовательно находим, что Антон стёр 60 : 6 = 10 точек, после чего осталось 60 − 10 = 50 точек."},{"text":"Боря стёр 50 : 5 = 10 точек, после чего осталось 50 − 10 = 40 точек."},{"text":"Вова стёр 40 : 4 = 10 точек, после чего осталось 40 − 10 = 30 точек."},{"text":"Эти 30 точек и стёрла Даша."}]},"10":{"steps":[{"text":"На колесе обозрения 12 кабин, расположенных на равном расстоянии друг от друга."},{"text":"Поворот на 1/12 оборота переместит каждую кабину на одну позицию. Белая кабина окажется наверху."}]},"11":{"steps":[{"text":"Последним по тропинке идёт слонёнок, поэтому, когда тропинка разделится на две, хотя бы по одной из них слонёнок будет идти последним в группе."},{"text":"Это условие не выполняется только в варианте В."},{"text":"Заметим, что все остальные варианты возможны – это легко подтвердить проверкой каждого из них."}]},"12":{"steps":[{"text":"Маршрут состоит из следующих стрелок: 3 вверх, 2 вправо, 3 влево и 3 вверх."},{"text":"Цепочка арифметических действий, соответствующих этим стрелкам, эквивалентна действию одной стрелки влево, то есть, делению на 2."},{"text":"Таким образом, получаем ответ 12 : 2 = 6."}]},"13":{"steps":[{"text":"В каждой сложенной из кубиков двойке содержится 2 кубика с пятью покрашенными гранями."},{"text":"Все остальные кубики имеют по 4 покрашенных грани."},{"text":"В сложенном из кубиков нуле кубиков с пятью покрашенными гранями нет."},{"text":"Таким образом, получаем ответ 66 − 3 · 2 = 60."}]},"14":{"steps":[{"text":"Налитая в аквариум вода занимает четверть его объёма."},{"text":"После того, как аквариум перевернули, объём воды не изменился, поэтому толщина слоя воды по-прежнему равна четверти высоты аквариума, то есть 1 метр."}]},"15":{"steps":[{"text":"Сложим плёнку по вертикальной линии. Детали левой и правой половин наложатся друг на друга.","image":"assets/grade-solution-steps/2022/task-15-1.webp","imageWidth":729,"imageHeight":300},{"text":"Получившуюся плёнку сложим по горизонтальной линии."},{"text":"Сравним расположение полосатых треугольников с вариантами. Подходит изображение А."}]},"16":{"steps":[{"text":"Разобьём имеющийся квадрат 4х4 на четыре квадрата 2х2."},{"text":"Тогда закрашенная фигура будет состоять из четырёх прямоугольных треугольников с катетами 5 и 2,5 см."},{"text":"Из них можно сложить прямоугольник со сторонами 10 и 2,5 см, площадь которого равна 10 · 2,5 = 25 см²."}]},"17":{"steps":[{"text":"Заметим что 2022, 2000 и 1999 − три последних особенных года."},{"text":"Так как Ева родилась в предыдущий особенный год, значит это был 2000 год."},{"text":"В этом случае в 2022 году Еве исполнится 22 года."}]},"18":{"steps":[{"text":"Для решения задачи рассмотрим две двойки в кругах, лежащих на той же диагонали, что и круг со знаком вопроса."},{"text":"Ближняя к знаку вопроса двойка исключает возможность поставить двойку в кругах слева и снизу от круга со знаком вопроса."},{"text":"Аналогично, дальняя двойка исключает возможность поставить двойку в четвёртый круг в этой группе."},{"text":"Таким образом, двойка может находиться в этой группе только на месте знака вопроса."}]},"19":{"steps":[{"text":"Сумма будет наибольшей, если 9 стоит в центральном круге."},{"text":"Заметим, что 8 + 3 = 7 + 4 = 6 + 5 = 11, поэтому 11 + 9 = 20 будет наибольшей возможной суммой, которую Саша может получить."}]},"20":{"steps":[{"text":"Легко убедиться, что единственная возможность поставить двойку − справа от единицы, тройку − справа от двойки, четвёрку − справа от тройки, пятёрку − под четвёркой, а шестёрку − под пятёркой, и так далее.","image":"assets/grade-solution-steps/2022/task-20-1.webp","imageWidth":204,"imageHeight":156},{"text":"Таким образом, в закрашенной клетке записано число 6."}]},"21":{"steps":[{"text":"42 − 18 = 24 см − разница в высоте между стопками из восьми и двух стаканов."},{"text":"Таким образом, каждый дополнительный стакан в стопке добавляет 24 : 6 = 4 см высоты."},{"text":"Получаем, что высота стопки из шести стаканов равна 18 + 4 · 4 = 34 см."}]},"22":{"steps":[{"text":"Заметим, что в третьем столбце сумма равна 3, значит в нём стоят 1 и 2."},{"text":"По условию задачи все числа в таблице различны, так как все животные разные."},{"text":"В четвёртом столбце сумма равна 7."},{"text":"Это может быть 1 + 6, 2 + 5 или 3 + 4."},{"text":"Но если 1 и 2 уже использованы, то остаётся единственный вариант, что в четвёртом столбце стоят 3 и 4."},{"text":"По аналогии находим, что во втором столбце стоят 5 и 6, а в первом − 7 и 8."},{"text":"Таким образом, наибольшая возможная сумма чисел в первой строке равна 8 + 6 + 2 + 4 = 20."}]},"23":{"steps":[{"text":"Рассмотрим коды на подсказках."},{"text":"Подсказка «4» говорит о том, что все три цифры (738) не используются в нашем коде."},{"text":"Из подсказок «1» и «2» следует, что это не может быть цифра 6, иначе получается противоречие."},{"text":"При этом цифра 8 в коде отсутствует, значит цифра 2 стоит на правильной позиции."},{"text":"Из подсказки «3», а также из того, что цифра 6 отсутствует в искомом коде, а цифра 2 должна стоять последней, получаем, что 0 будет стоять на первой позиции."},{"text":"Возвращаемся к подсказке «2»."},{"text":"Цифры 6 нет в коде, значит это может быть 1 или 4."},{"text":"Но мы уже знаем, что код 0?2 (неизвестна только цифра на второй позиции)."},{"text":"В подсказке говорится, что цифра верна, но она стоит на неправильной позиции, и значит это не может быть 1, которая тоже стоит на второй позиции."},{"text":"Остаётся только 4, и она удовлетворяет подсказке."},{"text":"Тогда искомый код – 042."}]},"24":{"steps":[{"text":"Каждая фигура состоит из трёх «башен», каждая башня состоит из трёх кубиков."},{"text":"Для того чтобы найти правильный ответ, нужно сопоставить места, где башни соединяются друг с другом."},{"text":"Это вариант В."}]},"25":{"steps":[{"text":"Все пять чисел могут быть записаны в закрашенном квадрате."},{"text":"Например, 3 + 5 − 6 = 2, 2 + 6 − 5 = 3, 2 + 5 − 3 = 4, 2 + 6 − 3 = 5, 3 + 5 − 2 = 6."}]},"26":{"steps":[{"text":"Так как все числа делятся на 7, то число 7 будет записано в центральном круге."},{"text":"В левом круге будет записано число 5, так как из всех чисел только 105 и 210 делятся на 5.","image":"assets/grade-solution-steps/2022/task-26-1.webp","imageWidth":249,"imageHeight":249},{"text":"В верхний круг будет записано число 3, так как 105 : 5 : 7 = 3."},{"text":"Аналогично, в нижнем круге записано число 6, так как 210 : 5 : 7 = 6."},{"text":"Тогда в правом круге будет стоять число 4, это можно проверить аналогичными вычислениями."},{"text":"Искомая сумма равна 4 + 6 + 7 = 17."}]},"27":{"steps":[{"text":"Рассмотрим грани, которые окажутся вокруг квадрата со знаком плюс после складывания развёртки."},{"text":"Сверим направление каждого минуса рядом с плюсом. Направление нарушается только в развёртке Б."}]},"28":{"steps":[{"text":"Посчитаем расстояния для всех вариантов:"},{"text":"Школа в А: 20 · 10 + 30 · 20 + 40 · 30 = 2000 км"},{"text":"Школа в В: 10 · 10 + 30 · 10 + 40 · 20 = 1200 км"},{"text":"Школа между В и С: 10 · 15 + 20 · 5 + 30 · 5 + 40 · 15 = 1000 км"},{"text":"Школа в С: 10 · 20 + 20 · 10 + 40 · 10 = 800 км"},{"text":"Школа в D: 10 · 30 + 20 · 20 + 30 · 10 = 1000 км"},{"text":"Таким образом, минимальное расстояние будет, если построить школу в деревне С."}]},"29":{"steps":[{"text":"Для наглядности к виду сверху допишем значения остальных двух измерений (смотри рисунок) и на каждом квадрате укажем, сколько кубиков находится в этом «столбике».","image":"assets/grade-solution-steps/2022/task-29-1.webp","imageWidth":243,"imageHeight":252},{"text":"После этого можем посчитать суммарное количество кубиков: 3 + 3 + 3 + 3 + 1 + 1 + 2 + 2 + 1 = 19."}]},"30":{"steps":[{"text":"Заметим, что в группе из трёх последовательно сидящих за столом людей, один может не носить шляпу, и допустима следующая рассадка НШШНШШНШШ..."},{"text":"(«Н» - нет шляпы, «Ш» - шляпа)."},{"text":"Так как ситуация ШШШ невозможна (иначе человек в шляпе, сидящий между двумя другими, должен бы был соврать), то максимально возможное количество людей в шляпах равно 20."}]}},"2023":{"1":{"steps":[{"text":"Как видим, числа в следующей строке на 8 больше, чем стоящие над ними числа в предыдущей строке."},{"text":"Исходя из этого условия, подбираем подходящий кусочек."},{"text":"Подходит только ответ В (20 – 12 = 8, 29 – 21 = 8), так как на других кусочках хотя бы одна из разностей не равна 8."}]},"2":{"steps":[{"text":"Начнем проверку с самого большого из представленных чисел: 800."},{"text":"Чтобы составить его, потребуется 19 спичек."},{"text":"Следующее число – 711."},{"text":"Чтобы составить его, потребуется 7 спичек."},{"text":"Значит, это и есть ответ на задание."}]},"3":{"steps":[{"text":"Видим, что когда мы склеим кубик, два кенгуру на желтом фоне и кенгуру на синем фоне окажутся по бокам (если принять центральный зелёный квадрат за верх получившегося кубика)."},{"text":"Таким образом, ответ А не подходит."},{"text":"Также заметим, что над головой и под ногами кенгуру на синем фоне расположены зеленые грани."},{"text":"Таким образом, исключаем и ответы В и Д."},{"text":"Теперь обратим внимание на расположение двух кенгуру на желтом фоне."},{"text":"При склеивании один из них окажется над головой другого."},{"text":"Тогда можем исключить и ответ Г."},{"text":"Остается ответ Б."},{"text":"Проверим его и увидим, что он действительно соответствует развертке."}]},"4":{"steps":[{"text":"Альпинист взбирается с самого нижнего до самого верхнего этажа башни включительно и делает по одному шагу на каждом этаже."},{"text":"Посчитаем общее количество этажей – их 21."},{"text":"Значит, не видны 21 – 9 = 12 шагов."}]},"5":{"steps":[{"text":"Для простоты описания назовем диски A, B, C, D и Е согласно уменьшению их размера (А – самый большой, Е – самый маленький)."},{"text":"Тогда Саша может построить следующие башни из четырёх дисков: ABCD, ABCE, ABDE, ACDE, BCDE."},{"text":"Всего 5 разных вариантов."}]},"6":{"steps":[{"text":"Лента Р расположена поверх M и Q."},{"text":"Лента Q расположена поверх M и N."},{"text":"А лента M расположена поверх N."},{"text":"Следовательно, N завязали первой, за ней M, потом Q, и последней завязали P."}]},"7":{"steps":[{"text":"Перебираем кусочки попарно, пока не получим полный шестиугольник."},{"text":"Видим, что это возможно только с кусочками 1 и 3.","image":"assets/grade-solution-steps/2023/task-07-1.webp","imageWidth":222,"imageHeight":192}]},"8":{"steps":[{"text":"Отверстия на круге расположены с разницей в 4 и 2 часа соответственно."},{"text":"Такая разница имеется только в ответе В."}]},"9":{"steps":[{"text":"Вова может получить фигуру А, приклеив серую деталь поверх чёрного круга, а затем приклеив по бокам две белых детали одну напротив другой."},{"text":"Может получить фигуру Б, также приклеив серую деталь поверх круга, а затем приклеив по бокам две белых детали."},{"text":"Может получить фигуру Г, приклеив поверх круга сначала одну белую деталь, затем поверх нее серую, и затем поверх вторую белую деталь."},{"text":"Также он может получить фигуру Д, наклеив серую деталь на чёрную, а затем белые поверх каждой из них."},{"text":"Однако получить композицию В невозможно, так как серая часть данной фигуры имеет форму разделённого на части исходного серого кусочка бумаги."}]},"10":{"steps":[{"text":"Если бы в каждом доме жило по 3 человека, то всего в 7 домах жило бы 7 · 3 = 21 человек."},{"text":"Но по условию их 25."},{"text":"25 – 21 = 4 – в стольких домах живут 4 человека."},{"text":"Тогда 3 человека живут в 7 – 4 = 3 домах."}]},"11":{"steps":[{"text":"Меняя первую цифру, заключаем, что ♢♦ = 9, △▲ = 0, □■ = 1."},{"text":"Тогда первое число – это 19, а ♥♡ = 2."},{"text":"Значит, следующее число, которое нужно записать – это 22, то есть ♥ ♥."}]},"12":{"steps":[{"text":"Периметр самого маленького квадрата 80."},{"text":"Вычислим длину его стороны: 80 : 4 = 20 мм."},{"text":"В нижнем ряду заметим, что высота средней плитки равна высоте двух маленьких плиток."},{"text":"Тогда длина стороны средней плитки 20 + 20 = 40 мм."},{"text":"В верхнем ряду заметим, что высота самой большой плитки равна высоте трёх маленьких плиток."},{"text":"Тогда длина стороны большой плитки 20 + 20 + 20 = 60 мм."},{"text":"Тогда длина ужа 20 · 3 + 60 · 2 + 40 · 5 + 20 · 2 = 420 мм."}]},"13":{"steps":[{"text":"Когда Аня посмотрела в зеркало, на часах было 21:51."},{"text":"Через 30 минут на часах будет 22:21."},{"text":"В зеркальном отражении это ответ Г."}]},"14":{"steps":[{"text":"Если Рома говорит правду, то Петя лжёт, и наоборот."},{"text":"Поскольку только один ребенок говорит правду, значит, это либо Петя, либо Рома, и, следовательно, Маша и Таня лгут."},{"text":"Это означает, что Таня разбила окно."},{"text":"При этом Рома – тот, кто сказал правду."}]},"15":{"steps":[{"text":"Начать имеет смысл с произведения 15."},{"text":"Оно получается только в случае, если его множители – 3 и 5."},{"text":"Одно из них входит в произведение 42, и это не может быть 5, так как 42 на 5 не делится нацело."},{"text":"Значит, слева пишем 5, и тогда самое крайнее правое число 30 : 5 = 6."},{"text":"Справа пишем 3, и тогда следующие два числа 42 : 3 = 14 и 28 : 14 = 2."},{"text":"Посчитаем сумму чисел в клетках: 6 + 5 + 3 + 14 + 2 = 30."}]},"16":{"steps":[{"text":"Покрасим верхний левый прямоугольник в цвет 1.","image":"assets/grade-solution-steps/2023/task-16-1.webp","imageWidth":207,"imageHeight":165},{"text":"Тогда есть два варианта цветов (цвет 2 или цвет 3) для второго прямоугольника в верхнем ряду."},{"text":"Основываясь на этих двух вариантах можно раскрасить остальную часть фигуры."},{"text":"Если мы выбираем для него цвет 2, то нижний левый прямоугольник должен быть покрашен в цвет 3, нижний правый – в цвет 1, а верхний правый должен быть того же цвета, что и нижний левый."},{"text":"Если выбираем для центрального верхнего прямоугольника цвет 3, то нижний левый и верхний правый прямоугольники должны быть покрашены в цвет 2, а нижний правый – в цвет 1."},{"text":"Аналогично по два варианта раскраски мы имеем, если покрасим верхний левый прямоугольник в цвет 2 или 3."},{"text":"Таким образом, общее количество вариантов равно 3 · 2 = 6."}]},"17":{"steps":[{"text":"Получить такую башню можно за три шага.","image":"assets/grade-solution-steps/2023/task-17-1.webp","imageWidth":489,"imageHeight":117},{"text":"Сначала нужно переставить два верхних бруска."},{"text":"Затем переставить все четыре (тогда башня просто перевернется вверх ногами)."},{"text":"И на последнем шаге переставить три верхних бруска."}]},"18":{"steps":[{"text":"Бобру и кенгуру нужно совершить по 11 прыжков, чтобы добраться до точки «Финиш»."},{"text":"Кенгуру при этом пройдет полтора круга."},{"text":"А заяц вообще никогда не сможет попасть на эту точку, так как она лежит на расстоянии нечётного количества точек от «Старта»."}]},"19":{"steps":[{"text":"Посчитаем суммы чисел в серых и белых клетках."},{"text":"В серых клетках: 1 + 2 + 7 + 4 + 6 = 20, в белых клетках: 3 + 5 + 13 + 8 + 11 = 40."},{"text":"Если мы хотим, чтобы суммы были одинаковыми, каждая сумма должна быть равна (20 + 40) : 2 = 30."},{"text":"Таким образом, мы должны увеличить сумму в серых клетках на 10, и в то же время уменьшить сумму в белых клетках на 10."},{"text":"То есть нужно найти пару чисел, которые отличаются на 10."},{"text":"Отличаются друг от друга на 10 только 1 и 11."},{"text":"Таким образом, чтобы выполнялось условие равенства сумм, необходимо поменять их местами."}]},"20":{"steps":[{"text":"Если шестерёнка А вращается по часовой стрелке, тогда маленькая шестеренка под ней будет вращаться против часовой стрелки, серая шестерёнка слева – по часовой стрелке, и левое нижнее колесо – против часовой стрелки.","image":"assets/grade-solution-steps/2023/task-20-1.webp","imageWidth":306,"imageHeight":381},{"text":"Тогда груз 1 будет опускаться, а груз 2 подниматься."},{"text":"В правой части при этом будет происходить следующее: маленькая шестерёнка под А вращается против часовой стрелки, тогда шестерёнка справа, соединенная с ней, будет вращаться также против часовой стрелки, тогда серая шестерёнка справа будет вращаться по часовой стрелке, маленькая шестерёнка под ней – против часовой стрелки, и правое нижнее колесо – по часовой стрелке."},{"text":"Тогда груз 3 будет подниматься, а груз 4 опускаться."},{"text":"Таким образом, получаем, что подниматься будут ящики 2 и 3."}]},"21":{"steps":[{"text":"В левой ячейке среднего ряда должны быть один круг и фигуры из центральной ячейки нижнего ряда.","image":"assets/grade-solution-steps/2023/task-21-1.webp","imageWidth":447,"imageHeight":252},{"text":"В правой ячейке среднего рядя должны быть один круг, один квадрат и фигуры из центральной ячейки нижнего ряда."},{"text":"Следовательно, в верхней ячейке окажутся два круга, один квадрат и удвоенное количество фигур из центральной ячейки нижнего ряда."},{"text":"Следовательно, в искомой ячейке должны быть один круг и один треугольник."}]},"22":{"steps":[{"text":"После работы четырёх аппаратов мы видим, что лист бумаги повернут трижды и имеет напечатанный рисунок."},{"text":"Значит, среди четырёх аппаратов три – поворот и один – печать."},{"text":"Заметим, что изображение повёрнуто дважды, а квадратик в углу соответствует тому, как если бы рисунок был нанесён после одного поворота."},{"text":"Значит, аппараты стоят в следующей последовательности: поворот (1) – печать (2) – поворот (1) – поворот (1)."}]},"23":{"steps":[{"text":"Наибольший общий делитель 24, 30, 66 равен 6."},{"text":"Таким образом, потребуется 120 : 6 + 1= 21 столбик."},{"text":"4 уже есть, значит нужно еще 21 – 4 = 17 столбиков."}]},"24":{"steps":[{"text":"Заметим, что в новой башне под каждым блоком с чётным номером n находится блок с номером n−1, а над каждым блоком с четным номером n находится блок с номером n−3."},{"text":"Ищем ответ, исходя из этого условия."},{"text":"Единственный подходящий вариант – Д."}]},"25":{"steps":[{"text":"Наименьшая сумма получается, если карточки выложены вверх цифрами 1, 2 и 3."},{"text":"Эта сумма равна 1 + 2 + 3 = 6."},{"text":"При повороте любой из карточек сумма увеличивается на 3, так как разница между двумя цифрами на каждой из карточек – 3."},{"text":"Повернуть можно одну, две или три карточки, при этом суммы также могут быть следующие: 9, 12 и 15."},{"text":"Всего четыре возможных варианта."}]},"26":{"steps":[{"text":"Вычислим стоимость указанных покупок, выразив их через стоимость кепок: 2 футболки = 3 кепки; 3 юбки = 8 футболок = 12 кепок, следовательно, 1 юбка = 4 кепки; 2 шляпы = 5 юбок = 20 кепок, следовательно, 1 шляпа = 10 кепок."},{"text":"Теперь узнаем стоимость каждой покупки, выраженную через стоимость кепок: А) 1 · 10 + 5 · 4 = 30; Б) 1 · 10 + 3 · 4 + 1 = 23; В) 8 · 4 + 6 · 3/2 = 41, Г) 37, Д) 3 · 4 + 3 = 15."},{"text":"Сравнивая, видим, что дороже всего обойдётся покупка В."}]},"27":{"steps":[{"text":"Если у игрока останется 1 плитка, этот игрок проиграет."},{"text":"Если у игрока останется 2, 3, 4, 5 или 6 плиток, этот игрок может оставить 1 плитку противнику и выиграет."},{"text":"Если у игрока останется 7 плиток, то сколько бы плиток (от 1 до 5) он ни убрал, у его противника останется больше 1-й плитки (от 6 до 2), следовательно, когда следующим ходом противник оставит ему 1 плитку, этот игрок проиграет."},{"text":"Если у игрока осталось 8, 9 или 10 (как в условии) плиток, этот игрок может оставить 7 плиток противнику, и таким образом и выиграть."},{"text":"Поэтому Соня должна оставить Рите 7 плиток."}]},"28":{"steps":[{"text":"На рисунке видно, что площади фигур А, В и D составляют ровно половину квадрата 2×2, а площадь фигуры С больше половины квадрата 2×2.","image":"assets/grade-solution-steps/2023/task-28-1.webp","imageWidth":285,"imageHeight":141},{"text":"Отсюда ответ – В.","image":"assets/grade-solution-steps/2023/task-28-2.webp","imageWidth":285,"imageHeight":141}]},"29":{"steps":[{"text":"Начнём рисовать путь по частям."},{"text":"Заметим, что некоторые круги соединены ровно с одним или ровно с двумя другими (на рисунке отмечены зелёным)."},{"text":"Путь должен пройти через эти круги, поэтому мы можем нарисовать соответствующую часть пути (красные линии на рисунке).","image":"assets/grade-solution-steps/2023/task-29-1.webp","imageWidth":453,"imageHeight":237},{"text":"Когда закончим, мы обнаружим несколько кругов (желтых на рисунке), которые теперь соединены ровно с двумя другими, потому что некоторые из их соседей уже есть на пути."},{"text":"На основе желтых кругов (на рисунке отмечены не все) можно добавить дополнительные части контура."},{"text":"Когда это будет сделано, будет достаточно большая часть пути, которую легко завершить, как показано на рисунке.","image":"assets/grade-solution-steps/2023/task-29-2.webp","imageWidth":456,"imageHeight":237}]},"30":{"steps":[{"text":"Посчитаем сумму всех написанных чисел: 1 + 2 + ... + 15 = 120."},{"text":"Значит, пятая группа чисел имеет сумму: 120 – 25 – 27 – 30 – 31 = 7."},{"text":"Три разных числа от 1 до 15 дают в сумме 7 только тогда, когда это 1, 2 и 4."},{"text":"Значит, число 4 содержится в пятой группе, чья сумма чисел равна 7."}]}},"2025":{"1":{"steps":[{"text":"Продолжим линии мозаики по обе стороны от серого участка, чтобы соседние плитки состыковались.","image":"assets/grade-solution-steps/2025/task-01-1.webp","imageWidth":366,"imageHeight":201},{"text":"Сравним получившийся рисунок с вариантами. Подходит фрагмент Б."}]},"2":{"steps":[{"text":"Если смотреть на конструкцию с обратной стороны: цифра 5 будет первой и будет читаться как 2, две цифры 2 будут читаться как 5, 0 останется без изменений."},{"text":"Вика увидит 2505."}]},"3":{"steps":[{"text":"Складываем правый закрылок, и видимыми остаются следующие цифры 3, 5, 2 и 6.","image":"assets/grade-solution-steps/2025/task-03-1.webp","imageWidth":192,"imageHeight":126},{"text":"Затем складываем левый закрылок, и после этого видимыми остаются цифры 3 и 5.","image":"assets/grade-solution-steps/2025/task-03-2.webp","imageWidth":102,"imageHeight":126},{"text":"3 + 5 = 8."}]},"4":{"steps":[{"text":"К каждой грани приклеены 1 полный квадрат и 4 половинки квадрата, то есть всего 3 квадрата."},{"text":"У куба 6 граней, значит всего 6 · 3 = 18 квадратов."}]},"5":{"steps":[{"text":"Посмотрим, какие ингредиенты лежат друг на друге. Под луком лежат только помидоры. Под грибами видны маслины и лук."},{"text":"Перец чили лежит поверх грибов и маслин. Получаем порядок снизу вверх: помидоры, лук, маслины, грибы, перец чили."},{"text":"Третьими были маслины."}]},"6":{"steps":[{"text":"Всего в сосуде 10 л."},{"text":"Тогда через каждое отверстие, после того как вынут пробки, вытечет по 10 : 5 = 2 л воды."},{"text":"Таким образом, 6 л попадёт в средний контейнер, 2 л сразу попадут в контейнер (В), и ещё 2 л вытекут через самую правую трубу."},{"text":"Из среднего контейнера выходят две трубы, через каждую из них вытечет 6 : 2 = 3 л воды."},{"text":"Одна из них ведет в контейнер (В)."},{"text":"Тогда всего в контейнер (В) попадёт 3 + 2 = 5 л."}]},"7":{"steps":[{"text":"После 6 поворотов шестиугольник вернётся в исходное положение."},{"text":"Тогда нужно сделать ещё 2 поворота.","image":"assets/grade-solution-steps/2025/task-07-1.webp","imageWidth":423,"imageHeight":90},{"text":"Видим, что итоговое положение соответствует ответу (А)."}]},"8":{"steps":[{"text":"Цена нижней позиции больше верхней."},{"text":"Тогда классический бургер стоит не менее 430 руб., бургер с беконом — не менее 460 руб., бургер с сыром — не менее 550 руб., а двойной бургер — не менее 610 руб."},{"text":"Если бы любой из бургеров был дороже, то бургер делюкс не мог бы стоить 680 руб."},{"text":"Следовательно, цены четырёх бургеров в середине списка составляют 430 руб., 460 руб., 550 руб. и 610 руб."},{"text":"Подходит только ответ Б."}]},"9":{"steps":[{"text":"Из условия мы знаем, что Арина заняла третье место, Миша – пятое, а Боря – шестое."},{"text":"Так как Юля оказалась между Ариной и Мишей, то она могла занять только четвёртое место."},{"text":"Остаются первое и второе места."},{"text":"Диана обогнала Федю, значит она заняла первое место, а Федя второе."},{"text":"Значит, Диана выиграла забег."}]},"10":{"steps":[{"text":"Всего на трёх полках 17 + 15 + 7 = 39 книг."},{"text":"Значит, на каждой полке должно быть 39 : 3 = 13 книг."},{"text":"Переместим 17 – 13 = 4 книги с верхней полки и 15 – 13 = 2 книги со средней полки на нижнюю полку."},{"text":"Так на каждой полке окажется по 13 книг."},{"text":"Со средней полки на нижнюю мы переместили 2 книги."}]},"11":{"steps":[{"text":"Пока второй кенгуру пробегает 1/4 пути, третий пробегает 1/5 пути."},{"text":"Второму кенгуру осталось пробежать 3/4 пути. Это втрое больше расстояния, которое он уже пробежал."},{"text":"За это же время третий кенгуру пробежит ещё 3/5 пути. Ему останется 1 − 1/5 − 3/5 = 1/5 пути."},{"text":"Весь путь составляет 10 км. Осталось пробежать 10 : 5 = 2 км."}]},"12":{"steps":[{"text":"Возможные варианты: 8 и 10, 8 и 11, 8 и 12, 9 и 11, 9 и 12, 10 и 12."},{"text":"Всего 6 вариантов."}]},"13":{"steps":[{"text":"Для каждого колеса разделим число закрашенных секторов на общее число секторов."},{"text":"Для колёс 1, 2, 3, 4 и 5 получим соответственно 2/8, 2/10, 1/6, 2/12 и 1/7."},{"text":"Наибольшее значение — 2/8 = 1/4. Колесо 1 даёт наибольший шанс на победу."}]},"14":{"steps":[{"text":"Попробуем разместить каждую предложенную фигуру на поле, совместив её клетки с подходящими клетками поля.","image":"assets/grade-solution-steps/2025/task-14-1.webp","imageWidth":609,"imageHeight":141},{"text":"На рисунке показано, как разместить фигуры А, Б, В и Д. Для фигуры Г подходящего места нет."}]},"15":{"steps":[{"text":"Первый спортсмен проплыл дистанцию за (2 мин + 8 с), второй – за (2 мин – 1 с), третий – за (2 мин + 3 с), четвёртый – за (2 мин – 5 с) и пятый – за (2 мин – 2 с)."},{"text":"Значит, четвёртый пловец проплыл быстрее всех."}]},"16":{"steps":[{"text":"Площадь исходного листа составляет 16 + 9 = 25 см²."},{"text":"Тогда длина стороны этого квадрата – 5 см, а его периметр равен 4 · 5 = 20 см."},{"text":"Периметр креста такой же."}]},"17":{"steps":[{"text":"На карточке А у числа 543 сумма цифр 12. В числе 11□ недостающая цифра должна быть 10, поэтому А отпадает."},{"text":"На карточке Б сумма цифр 58□ не меньше 13. У числа 11□ она не больше 11. В варианте Г у числа 211 сумма цифр 4, а у 6□□ она не меньше 6."},{"text":"В варианте Д у числа 777 сумма цифр 21, а две недостающие цифры числа 2□□ должны были бы дать в сумме 19. Две цифры дают не больше 18."},{"text":"В варианте В сумма цифр 982 равна 19. Число 199 даёт такую же сумму. Значит, подходит карточка В."}]},"18":{"steps":[{"text":"Заметим, что без двух верхних и двух правых квадратиков фигура превращается в прямоугольник, который делится диагональю SE на два равных треугольника.","image":"assets/grade-solution-steps/2025/task-18-1.webp","imageWidth":249,"imageHeight":297},{"text":"Так как выделенные верхняя и боковая части тоже между собой одинаковы, то этот отрезок делит всю фигуру на две равные по площади фигуры."}]},"19":{"steps":[{"text":"Поскольку 0 уже стоит, все остальные ячейки во второй строке, третьем столбце и диагональ, проходящая через ячейку с 0, должны быть заполнены цифрой 1."},{"text":"Если теперь мы поместим 0 или 1 в какую-либо одну из ячеек с вопросительным знаком и заполним остальные ячейки, увидим, что сумма чисел в ячейках с вопросительными знаками будет равна 2.","image":"assets/grade-solution-steps/2025/task-19-1.webp","imageWidth":552,"imageHeight":165},{"text":"Есть два варианта заполнения таблицы."}]},"20":{"steps":[{"text":"Наибольшее трёхзначное число – то, которое начинается с 9."},{"text":"Но первая цифра во втором числе Кати не может быть 9, так как третье число по условию больше второго."},{"text":"Поэтому её второе число должно начинаться с 8."},{"text":"Если не использовать цифру 9, то максимально возможным из всех чисел, стоящих на втором месте, может быть только 876."},{"text":"Наименьшее трёхзначное число – то, которое начинается с 1."},{"text":"Но первая цифра во втором числе Лёши не может быть 1, так как первое число по условию меньше второго."},{"text":"Поэтому его второе число должно начинаться с 2."},{"text":"Если не использовать цифру 1, то минимально возможным из всех чисел, стоящих на втором месте, может быть только 234."},{"text":"Их разность составляет 876 – 234 = 642."}]},"21":{"steps":[{"text":"Заметим, что бананов и груш изначально 9 + 6 = 15, что в точности равно количеству яблок после превращения."},{"text":"Это означает, что ВСЕ бананы и груши превратились в яблоки."},{"text":"То есть ни один банан не превратился в грушу, потому что тогда из бананов и груш получилось бы меньше 15 яблок."},{"text":"Аналогично, ни одна груша не превратилась в банан."},{"text":"Значит, 10 яблок превратились в 7 бананов и 3 груши."}]},"22":{"steps":[{"text":"Сторона квадрата 10 см, поэтому его площадь 10 · 10 = 100 см²."},{"text":"На рисунке виден большой треугольник площадью в половину квадрата, то есть 50 см². Маленький треугольник занимает четверть квадрата, то есть 25 см².","image":"assets/grade-solution-steps/2025/task-22-1.webp","imageWidth":615,"imageHeight":180},{"text":"Площадь выделенной фигуры равна разности этих площадей: 50 − 25 = 25 см²."}]},"23":{"steps":[{"text":"Поделим фигуру на части, каждая из которых состоит из трёх клеток.","image":"assets/grade-solution-steps/2025/task-23-1.webp","imageWidth":165,"imageHeight":165},{"text":"Увидим, что такое разбиение возможно только одним способом."},{"text":"Звезда в этом случае окажется в одном кусочке с буквой Е."}]},"24":{"steps":[{"text":"Два ответа противоречат друг другу, значит диалог происходит в один из дней, когда Дима лжёт (вторник, четверг или суббота)."},{"text":"Следовательно, оба утверждения неверны."},{"text":"И тогда этот диалог не может происходить в субботу или вторник (день перед средой)."},{"text":"Следовательно, единственный возможный день – четверг."}]},"25":{"steps":[{"text":"Чтобы использовать наименьшее количество деталей, Лена должна будет сложить крест, как показано на рисунке.","image":"assets/grade-solution-steps/2025/task-25-1.webp","imageWidth":234,"imageHeight":234},{"text":"Видим, что для этого ей потребуется 13 деталей."}]},"26":{"steps":[{"text":"Сравнивая левую и правую стороны всей конструкции, видим, что два блока с точками весят столько же, сколько три блока с крестиком, значит блоки с точками тяжелее."},{"text":"На левой части весов мы видим, что блок с крестиком и блок с линией вместе весят столько же, сколько два блока с точками."},{"text":"Но поскольку мы уже выяснили, что блоки с крестиком легче, чем с точками, то для равновесия блок с линией должен быть тяжелее."},{"text":"Таким образом, правильная последовательность блоков, расположенных по убыванию веса, приведена в ответе A."}]},"27":{"steps":[{"text":"Если сумма двух цифр содержит 1 в качестве слагаемого, то эта сумма всегда будет меньше или равна 10."},{"text":"Тогда у квадрата, содержащего 1, такими будут все суммы, написанные на соединяющих его линиях."},{"text":"Единственный квадрат с таким свойством расположен в нижнем правом углу.","image":"assets/grade-solution-steps/2025/task-27-1.webp","imageWidth":249,"imageHeight":246},{"text":"Поэтому положение 1 определено однозначно."},{"text":"Остальные квадраты легко заполняются числами, исходя из указанных сумм."},{"text":"Сумма чисел в закрашенной строке: 5 + 4 + 9 = 18."}]},"28":{"steps":[{"text":"Проверим каждую из конструкций: (A) – невозможно, потому что по крайней мере один из кубиков в верхней части должен быть из второго блока."},{"text":"Но тогда не получится разместить два других блока так, чтобы получилась такая конструкция."},{"text":"(Б) – невозможно, потому что второй блок «двухэтажный», значит хотя бы один кубик должен возвышаться над конструкцией."},{"text":"(В) – невозможно, потому что кубик в верхней части очевидно относится ко второму блоку, но тогда нет возможности разместить два других блока так, чтобы получилась такая конструкция."},{"text":"(Г) – возможно, так как один кубик из второго блока и один кубик из третьего блока находятся в верхней части конструкции: (Д) – невозможно, потому что в верхней части может быть не более 3 кубиков."}]},"29":{"steps":[{"text":"Пусть у Серёжи сначала было m шоколадок. Тогда у Гены было 3m шоколадок."},{"text":"Гена передал Серёже четверть своих шоколадок. У Гены осталось 3m − 3m/4, у Серёжи стало m + 3m/4."},{"text":"У Гены стало на 6 шоколадок больше, чем у Серёжи. Составим уравнение 3m − 3m/4 − 6 = m + 3m/4."},{"text":"Получаем m = 12. Сначала у Гены было 36 шоколадок, у Серёжи — 12. Разница составляла 24 шоколадки."}]},"30":{"steps":[{"text":"На 230 рублей можно купить не более 7 цветков первого типа, 5 цветков второго типа или 4 цветка третьего типа."},{"text":"При этом ни один из этих вариантов не стоит ровно 230 руб."},{"text":"Значит букеты будут состоять из цветков нескольких типов."},{"text":"Возможные варианты: 1 · 30 + 5 · 40 = 230 1 · 30 + 4 · 50 = 230 2 · 30 + 3 · 40 + 1 · 50 = 230 3 · 30 + 1 · 40 + 2 · 50 = 230 5 · 30 + 2 · 40 = 230 6 · 30 + 1 · 50 = 230 2 · 40 + 3 · 50 = 230 Итого 7 вариантов букетов."},{"text":"Другие букеты не дадут в сумме ровно 230 руб."}]}},"2026":{"1":{"steps":[{"text":"Посмотрим на три соседние плитки в центральном ряду. Эта последовательность исключает ответы Б, В и Д.","image":"assets/grade-solution-steps/2026/task-01-1.webp","imageWidth":186,"imageHeight":69},{"text":"В верхнем ряду перед плиткой с четырьмя треугольниками стоит плитка со звездой.","image":"assets/grade-solution-steps/2026/task-01-2.webp","imageWidth":66,"imageHeight":66},{"text":"В нижнем ряду после плитки с концентрическими кругами стоит плитка с цветком. Обе соседние плитки стоят на своих местах только в варианте Г.","image":"assets/grade-solution-steps/2026/task-01-3.webp","imageWidth":66,"imageHeight":66}]},"2":{"steps":[{"text":"Две круглые бусины стоят рядом в браслетах А, В и Д."},{"text":"Из этих трёх браслетов только в браслете В две квадратные бусины нигде не стоят рядом."}]},"3":{"steps":[{"text":"Посмотрим, куда повёрнуты чёрные элементы узора у краёв отверстия."},{"text":"Подбираем деталь, на которой элементы продолжают узор у каждого края. На рисунке подходящая деталь Г выделена синим.","image":"assets/grade-solution-steps/2026/task-03-1.webp","imageWidth":348,"imageHeight":180}]},"4":{"steps":[{"text":"Острый угол на каждом краю корпуса вынуждает положить по трапеции. Между ними у нижнего края остаётся два острых угла. Их заполняет перевёрнутая трапеция."},{"text":"Правая надстройка занимает один квадрат. У большой надстройки шесть выпуклых прямых углов. Деталь-квадрат может заполнить не больше двух таких углов, а вместо квадрата для одного прямого угла понадобятся два острых угла трапеций."},{"text":"В большой надстройке 16 клеток. Меньше четырёх деталей заняли бы эту площадь только как две трапеции или одна трапеция и два квадрата. Ни один из вариантов не заполняет все шесть прямых углов."},{"text":"На рисунке видно, как три трапеции и пять квадратов заполняют корабль. Минимум — восемь деталей.","image":"assets/grade-solution-steps/2026/task-04-1.webp","imageWidth":369,"imageHeight":165}]},"5":{"steps":[{"text":"Сумма всех чисел на кубике равна 1 + 2 + 3 + 4 + 5 + 6 = 21."},{"text":"Сумма чисел на трёх гранях около одной из вершин равна 14."},{"text":"Тогда сумма трёх чисел на других гранях равна 21 − 14 = 7."},{"text":"Следовательно, эти числа — 1, 2 и 4."}]},"6":{"steps":[{"text":"Снизу фонарики имеют такие формы: круг, шестиугольник, прямоугольный ромб, круг."},{"text":"Эта последовательность изображена в ответе Б."}]},"7":{"steps":[{"text":"Положим вторую деталь в пустое место первой. Останутся два пустых места для соседних лепестков.","image":"assets/grade-solution-steps/2026/task-07-1.webp","imageWidth":105,"imageHeight":66},{"text":"Одной деталью эти два места закрыть невозможно, поэтому понадобится как минимум четыре детали."},{"text":"Четырёх деталей достаточно. На рисунке показано, как их расположить.","image":"assets/grade-solution-steps/2026/task-07-2.webp","imageWidth":105,"imageHeight":99}]},"8":{"steps":[{"text":"Мысленно разрежем бумагу по сплошным линиям в каждом варианте."},{"text":"Затем согнём части по пунктирным линиям. Нужная фигура получается у варианта Д."}]},"9":{"steps":[{"text":"Максим съел четверть из 8 кусков, то есть 2 куска."},{"text":"Осталось 8 − 2 = 6 кусков."},{"text":"Галя съела половину из этих 6 кусков, то есть 3 куска."},{"text":"Значит, осталось 6 − 3 = 3 куска."}]},"10":{"steps":[{"text":"Правильный ответ является зеркальным отображением исходной картинки."},{"text":"Заметим, что полоски на рисунке должны быть параллельны короткой стороне, значит ответы А и В не подходят."},{"text":"Также заметим, что ближе к чёрной области расположено два кружочка, а не один, значит ответ Б также не верный."},{"text":"Ответ Д – это исходная картинка, повёрнутая вверх ногами (а не её обратная сторона)."},{"text":"А ответ Г является зеркальным отображением Дашиной картинки относительно её длинной стороны – то есть именно тем, что изображено на обратной стороне прозрачного листа."}]},"11":{"steps":[{"text":"Для 30 человек потребуется 10 автомобилей."},{"text":"Десятый автомобиль отправляется в 13:18 и прибывает через 10 минут, то есть в 13:28."}]},"12":{"steps":[{"text":"Только вариант Г делит фигуру на две одинаковые части."},{"text":"В вариантах A и Д две части имеют разный размер."},{"text":"В вариантах Б и В две части имеют разную форму."}]},"13":{"steps":[{"text":"Часы показывают 15:69."},{"text":"Цифру 6 необходимо переставить, поскольку 6 не может находиться в разряде десятков минут."},{"text":"Правильная цифра на этой позиции должна быть меньше 6, поэтому реальное время — либо 65:19, либо 16:59."},{"text":"Поскольку 65:19 недопустимо, остаётся единственный вариант — 16:59, что означает, что цифры 5 и 6 переставлены местами."},{"text":"Через минуту фактическое время будет 17:00."},{"text":"Перестановка цифр даёт 10:70."}]},"14":{"steps":[{"text":"На полоске пять линий сгиба."},{"text":"Обратим внимание, что три средние линии параллельны."},{"text":"Следовательно, правильным может быть только ответ Г."},{"text":"Проверка остальных сгибов подтверждает это."}]},"15":{"steps":[{"text":"Сумма 0 + 1 + 2 + 3 + 4 + 5 + 6 = 21."},{"text":"Так как все числа размещаются в трёх рядах, то сумма в каждом ряду будет 21 : 3 = 7."},{"text":"Чтобы в каждом ряду сумма была равна 7, 0 должен оказаться в среднем ряду."},{"text":"Тогда произведение чисел в среднем ряду всегда будет 0."},{"text":"Например: 5 + 2 = 7, 6 + 0 + 1 = 7, 3 + 4 = 7."}]},"16":{"steps":[{"text":"Для решения нет необходимости складывать все отмеченные числа."},{"text":"Достаточно заметить, что полоска сгибается каждый раз симметрично относительно середины."},{"text":"После первого сгибания напротив каждого из чисел (обозначим его x) находится число (17 – x), а сумма каждой пары равна 17 (16 + 1, 15 + 2 и так далее)."},{"text":"Мысленно «склеим» полоску и «заменим» её на однослойную полоску длиной в 8 клеточек, где в каждой клетке написано число 17."},{"text":"Теперь очевидно, что после следующего сгиба сумма «склеенных» чисел удвоится."},{"text":"Далее так же мысленно заменим её на полоску в 4 клетки, на каждой клетке которой написано число 34."},{"text":"Когда мы сложим и мысленно заменим и её, у нас останется полоска из двух клеток, на каждой клетке которой будет написано число 68."},{"text":"Это и есть сумма тех чисел, которые окажутся в клетках, проколотых иголкой."}]},"17":{"steps":[{"text":"Периметр одной фигуры 22 см."},{"text":"Общий периметр 4-х таких фигур: 4 · 22 = 88 см."},{"text":"В вертушке, сложенной из этих фигур есть ровно четыре общих (внутренних) стороны AB."},{"text":"Когда многоугольники имеют общую сторону длиной L, их общий периметр уменьшается на 2L."},{"text":"Тогда периметр вертушки равен: 88 − 2 · 4 · AB = 56, отсюда 8 · AB = 32, AB = 4 см."}]},"18":{"steps":[{"text":"Пока в коробке остаётся достаточно ирисок, Никита может по очереди брать 1, 4, 7, 10... ирисок, Петя — 2, 5, 8, 11... ирисок, Саша — 3, 6, 9... ирисок."},{"text":"Таким образом, возможные суммы для Пети: 2, 7, 15, 26 и так далее."},{"text":"То, что Петя получил только 25 = 2 + 5 + 8 + 10 ирисок, означает, что он был последним мальчиком, который взял ириски из коробки, и взял он только 10 ирисок вместо 11."},{"text":"Отсюда находим изначальное количество ирисок в коробке: 1 + 2 + 3 + ... + 10 + 10 = 65."}]},"19":{"steps":[{"text":"Короткая сторона белого прямоугольника равна 15 − 7 = 8 см."},{"text":"Тогда короткая сторона серого прямоугольника равна 29 − (8 + 15) = 6 см."},{"text":"Таким образом, длина стороны AB равна 29 + 6 = 35 см."}]},"20":{"steps":[{"text":"Количество учеников равно 80 : 4 = 20."},{"text":"Тогда 20 − 8 = 12, 12 · 6 = 72, 72 : 8 = 9."},{"text":"Таким образом, каждый ученик изначально получил по 9 яблок."},{"text":"Общее количество яблок равно 20 · 9 = 180."}]},"21":{"steps":[{"text":"В каждой фразе указан ровно один правильный город на правильной позиции."},{"text":"Два других города в этой фразе неверны или неверна их позиция."},{"text":"В первых двух фразах первый город — Москва."},{"text":"Поскольку только один элемент в каждой фразе может быть верным, Москва не может быть первым городом."},{"text":"В третьей фразе первым городом является Тула."},{"text":"Это и есть правильный первый город."},{"text":"В первой фразе второй город — Воронеж, во второй и третьей фразах — Рязань."},{"text":"Поскольку только один город в каждой фразе может быть верным, Рязань не может быть вторым."},{"text":"Таким образом, второй город — Воронеж."},{"text":"В первой и третьей фразе третий город — Омск."},{"text":"Поскольку только один элемент в каждой фразе может быть верным, Омск не может быть третьим."},{"text":"Третий город во втором утверждении, Казань, должен быть правильным."},{"text":"Фактический маршрут подозреваемого был Тула → Воронеж → Казань."}]},"22":{"steps":[{"text":"Посчитаем целые клетки, а по две половинки будем считать за одну клетку."},{"text":"Фигуры А, Б, Г и Д занимают по 7 клеток. Фигура В занимает 7,5 клетки и отличается от остальных."}]},"23":{"steps":[{"text":"У Даши и Феди вместе не более 4 + 5 = 9 цветков, поэтому у Зои не более 9 : 3 = 3 цветков, то есть 1, 2 или 3 цветка."},{"text":"Если у Зои 1 цветок, то у Даши и Феди будет 1 и 2 цветка."},{"text":"Это невозможно, так как есть только один горшок с 1 цветком."},{"text":"Если у Зои 3 цветка, то у Даши и Феди будет 4 и 5."},{"text":"Тогда у Риты должен быть либо 1, либо 2, и, следовательно, у Феди и Ксюши вместе либо 2, либо 4."},{"text":"Это также невозможно, так как только у одного Феди уже 4 или 5 цветков."},{"text":"Следовательно, у Зои 2 цветка, а у Даши и Феди 1 и 5 цветков в каком-то порядке."},{"text":"У Ксюши должно быть нечётное количество цветков, потому что у Феди и Ксюши вместе чётное количество цветков."},{"text":"Значит, у Ксюши 3 цветка, а у Риты 4."},{"text":"И наконец, у Феди 2 · 4 − 3 = 5."}]},"24":{"steps":[{"text":"Две гири слева весят столько же, сколько и пять гирь справа."},{"text":"Таким образом, сумма весов этих семи гирь должна быть максимально возможной, чтобы сумма весов двух неиспользуемых гирь была минимально возможной."},{"text":"Следовательно, сумма весов двух гирь на левой чаше должна быть максимальной."},{"text":"Если это гири 9 кг и 8 кг, их вес будет 17 кг."},{"text":"Тогда сумма весов пяти гирь на правой чаше тоже составит 17 кг, а сумма весов двух неиспользуемых гирь составит 45 – 2 · 17 = 45 − 34 = 11."},{"text":"На самом деле, это возможно: 1 + 2 + 3 + 4 + 7 = 17 и 5 + 6 = 11."}]},"25":{"steps":[{"text":"Существует пять нечётных цифр: 1, 3, 5, 7, 9."},{"text":"Поскольку комбинация состоит из четырёх нечётных цифр, ровно одна из этих пяти цифр не используется."},{"text":"При этом используемые цифры либо увеличиваются, либо уменьшаются слева направо."},{"text":"Таким образом, получается 5 · 2 = 10 возможных комбинаций: 3579 или 9753, 1579 или 9751, 1379 или 9731, 1359 или 9531, 1357 или 7531."}]},"26":{"steps":[{"text":"Складываем числа в каждой строке и каждом столбце."},{"text":"И по строкам, и по столбцам получим 4 суммы: 19, 20, 22 и 24.","image":"assets/grade-solution-steps/2026/task-26-1.webp","imageWidth":255,"imageHeight":252},{"text":"И тогда стереть нужно числа, стоящие на пересечении столбца и строки с одинаковой суммой."},{"text":"Это 7, 5, 5 и 8."},{"text":"Их сумма равна 7 + 5 + 5 + 8 = 25."}]},"27":{"steps":[{"text":"Если мы посмотрим на первую строку и второй столбец, сумма чисел в которых одинакова, мы увидим, что два серых круга должны содержать одно и то же число."},{"text":"Обозначим его g."},{"text":"Пусть a — число во второй строке первого столбца."},{"text":"Тогда g + a = 16, a – g = 4."},{"text":"Из второго равенства a = 4 + g."},{"text":"Подставим это выражение вместо a в первое равенство: g + 4 + g = 16, 2g = 12 – это и есть сумма чисел в двух серых кругах."}]},"28":{"steps":[{"text":"Поскольку одна из кружек Гермионы и Фреда маленькая, кружки Гарри и Рона должны быть большими."},{"text":"Следовательно, кружка Джорджа маленькая."},{"text":"Поскольку у одной из кружек Гарри и Рона белая ручка, у кружек Гермионы и Фреда чёрные ручки."},{"text":"Следовательно, у кружки Джорджа белая ручка."},{"text":"Кружка Джорджа — это кружка Б."}]},"29":{"steps":[{"text":"В верхнем ряду необходимо разместить ровно одни качели."},{"text":"Кроме того, в закрашенной области должны быть одни качели."},{"text":"Таким образом, в ячейке в верхнем левом углу качелей быть не может.","image":"assets/grade-solution-steps/2026/task-29-1.webp","imageWidth":174,"imageHeight":174},{"text":"В области, содержащей две ячейки, одна из них не может содержать качели."},{"text":"Поэтому качели должны быть размещены во второй ячейке, отмеченной галочкой."},{"text":"В результате все ячейки в той же строке или столбце, что и эта ячейка, а также все ее соседние ячейки, не могут содержать качели."},{"text":"На рисунке все эти ячейки отмечены крестиком.","image":"assets/grade-solution-steps/2026/task-29-2.webp","imageWidth":174,"imageHeight":177},{"text":"На полученной схеме одна из цветных ячеек обязательно должна содержать качели."},{"text":"Но каждая из этих двух цветных ячеек примыкает как к ячейке Г, так и к ячейке Д."},{"text":"Поэтому, если качели разместить в любой из цветных ячеек, ни в ячейке Г, ни в ячейке Д качелей не будет."},{"text":"Следовательно, единственный возможный вариант — разместить качели в ячейке В."},{"text":"На третьей схеме показан один из допустимых способов размещения всех качелей.","image":"assets/grade-solution-steps/2026/task-29-3.webp","imageWidth":174,"imageHeight":177}]},"30":{"steps":[{"text":"Последовательность цифр «2026» можно встретить на границах двух соседних чисел, первое из которых оканчивается на 20, а следующее начинается на 26 (это числа 2620 и 2621); или первое из которых оканчивается на 202, а следующее начинается на 6 (это числа 6202 и 6203)."},{"text":"Нет варианта, когда первое оканчивается на 2, а второе начинается на 026."},{"text":"Таким образом, искомую последовательность можно встретить на границе чисел: 2620-2621 и 6202-6203, плюс само число 2026."},{"text":"Всего 3 раза."}]}}};
